// The Touch test: where the pointer is, the gesture the frame made of it, and
// the path of a drag. Held down and moved, a finger, a pen or a mouse leaves a
// trail from where it went down (the ring) to where it is (the dot, red while
// held, blue once lifted), with a small dot for every position the glass
// reported. The trail stays until the next press, so a whole gesture can be
// read after.
//
// The app hears the pointer itself (config.json "events", onEvent). A move
// adds its point and asks for a render. Moves that arrive while a render runs
// reach the scene as the newest one alone (the contract's coalesce), carrying
// where the others were in `points`, and those join the trail too: the frame
// draws as fast as its panel goes, every move on an LCD and one partial
// update after another on e-paper, each with all that came meanwhile, and no
// position of the finger is lost however slow the glass. On a panel without
// colors (greys, black and white) it is drawn in black, which e-paper's fast
// waveform draws exactly while a finger is down: a grey would go up as a
// halftone until the glass settles.
//
// The trail is drawn into a canvas (frameos.canvas) the size of the panel, a
// render drawing only the points that came since the one before, and the
// frame repaints only what was drawn: a render costs the same at the first
// move and the thousandth. The pointer, the ring, the hairlines and the words
// are drawn over it each render.
//
// Positions are in panel pixels, while a big panel runs this app at a render
// scale (app.frame.scale, e.g. 2 at 1600x1200): the canvas it is told about is
// the panel divided by the scale and the drawing is stretched back. So the
// positions and the sizes that should stay as they are (the hairlines, the
// trail, the text) are worked out in panel pixels and divided by it.

// The most points a trail keeps. Past it every other one goes, the press and
// the newest stay: a long drag keeps its whole shape in a bounded piece of an
// ESP32's JS heap.
const MAX_POINTS = 1024
// A position this close to the trail's last point (panel pixels) moves the
// dot and adds no point.
const MIN_STEP = 2
// The trail goes into the canvas in pieces of at most this many points, so no
// draw holds a big tree (a fresh canvas draws a whole trail again); without a
// canvas (no memory for one), each piece is a path of its own in the picture,
// and a drag repaints its newest piece and not the whole trail.
const PIECE = 32

type Seen = {
  last: string // what the scene heard last, in words
  x: number // where, in panel pixels
  y: number
  down: boolean // the trail's pointer is held
  id: number // the pointer the trail follows
  presses: number // presses so far: a new one starts a new trail
  count: number // events heard, moves left out
  moves: number // positions the glass reported since the press
  trail: number[] // x0, y0, x1, y1, ... since the press
}

// Kept with frameos.remember at every render and every event but a move: an
// ESP32 short of memory drops the interpreter, and this module, after a render.
let seen: Seen | null = null

function load(): Seen {
  if (!seen) {
    const kept: any = frameos.recall('seen')
    seen = kept && Array.isArray(kept.trail) ? kept : {
      last: 'Touch, click or drag the picture', x: 0, y: 0, down: false, id: -1, presses: 0, count: 0, moves: 0, trail: [],
    }
  }
  return seen
}

// The canvas the trail is drawn into, while the interpreter lives: how many of
// the trail's points it holds, and the press and colors they were drawn for.
let drawn = 0
let drawnLook = ''

const keep = () => frameos.remember('seen', seen)

function add(s: Seen, x: number, y: number) {
  const t = s.trail
  const n = t.length
  if (n >= 2 && Math.abs(t[n - 2] - x) < MIN_STEP && Math.abs(t[n - 1] - y) < MIN_STEP) return
  if (n >= MAX_POINTS * 2) {
    // Thinned where the canvas holds it already: the points it has yet to
    // draw stay, and so does the last one it drew, which they go on from.
    const kept = drawn >= 1 && drawn <= n / 2 ? drawn - 1 : n / 2 - 1
    const thinned: number[] = []
    for (let i = 0; i < kept; i += 2) thinned.push(t[2 * i], t[2 * i + 1])
    if (drawn >= 1 && drawn <= n / 2) drawn = thinned.length / 2 + 1
    for (let i = kept; i < n / 2; i++) thinned.push(t[2 * i], t[2 * i + 1])
    s.trail = thinned
  }
  s.trail.push(x, y)
}

const who = (p: any) => `${p.pointerType} ${p.pointerId}`

export function onEvent(app: FrameOSApp, context: FrameOSContext) {
  const s = load()
  const p = context.payload || {}
  const event = context.event
  const x = Number.isFinite(p.x) ? Math.round(p.x) : s.x
  const y = Number.isFinite(p.y) ? Math.round(p.y) : s.y
  if (event === 'pointerMove') {
    // Only the pointer that pressed, while it is held: a mouse moving with
    // nothing pressed, or another finger, draws nothing and costs no render.
    if (!s.down || p.pointerId !== s.id) return false
    if (p.buttons === 0) {
      // Its release went somewhere else (another scene showed meanwhile).
      s.down = false
      keep()
      return true
    }
    // Where the moves this one stands for went, oldest first.
    const passed = Array.isArray(p.points) ? p.points : []
    for (let i = 0; i + 1 < passed.length; i += 2) {
      if (Number.isFinite(passed[i]) && Number.isFinite(passed[i + 1])) {
        add(s, Math.round(passed[i]), Math.round(passed[i + 1]))
        s.moves++
      }
    }
    if (x === s.x && y === s.y && passed.length === 0) return false
    s.x = x
    s.y = y
    s.moves++
    s.last = `pointerMove (${who(p)})`
    add(s, x, y)
    // Kept at the next render or at the lift, not at every move.
    return true
  }
  s.x = x
  s.y = y
  s.count++
  if (event === 'pointerDown') {
    s.down = true
    s.id = p.pointerId
    s.presses = (s.presses || 0) + 1
    s.moves = 0
    s.trail = [x, y]
    s.last = `pointerDown (${who(p)}, button ${p.button})`
  } else if (event === 'pointerUp' || event === 'pointerCancel') {
    if (s.down && p.pointerId === s.id) {
      add(s, x, y)
      s.down = false
    }
    s.last = `${event} (${who(p)})`
  } else if (event === 'swipe') {
    s.last = `swipe ${p.direction}`
  } else if (event === 'longPress') {
    s.last = `longPress (${p.durationMs} ms)`
  } else {
    s.last = event
  }
  keep()
  return true
}

export function get(app: FrameOSApp, context: FrameOSContext) {
  const s = load()
  keep() // the moves since an event last kept it
  const scale = app.frame.scale || 1
  const width = context.imageWidth ?? app.frame.width
  const height = context.imageHeight ?? app.frame.height
  const at = (v: number) => Math.round((v / scale) * 10) / 10
  const radius = Math.max(6, Math.round(Math.min(width * scale, height * scale) / 24)) / scale
  // Black where the panel shows no colors; the pointer held is a solid dot
  // there and a ring once lifted.
  const mono = app.frame.color === false
  const ink = mono ? '#000000' : s.down ? '#d13c3c' : '#2f6fe0'
  const pale = mono ? '#000000' : s.down ? '#f0a8a8' : '#a8c2f2'
  const hairColor = mono ? '#000000' : '#999999'
  const x = at(s.x)
  const y = at(s.y)
  const r = at(3)

  const t = s.trail
  const points = t.length / 2
  // Points first..end-1 of the trail: the line through them, and a dot on
  // each, in the panel's pixels divided by `scaleBy`.
  const strokes = (first: number, end: number, scaleBy: number) => {
    let line = ''
    let dots = ''
    const d = 3 / scaleBy
    for (let i = first; i < end; i++) {
      const px = Math.round((t[2 * i] / scaleBy) * 10) / 10
      const py = Math.round((t[2 * i + 1] / scaleBy) * 10) / 10
      line += `${i === first ? 'M' : 'L'}${px} ${py}`
      dots += `M${Math.round((px - d) * 10) / 10} ${py}a${d} ${d} 0 1 0 ${2 * d} 0a${d} ${d} 0 1 0 ${-2 * d} 0`
    }
    return [
      end - first > 1 ? <path d={line} fill="none" stroke={pale} strokeWidth={d} strokeLinecap="round" strokeLinejoin="round" /> : [],
      <path d={dots} fill={ink} />,
    ]
  }
  // The canvas is in panel pixels, stretched to the picture's size.
  const canvas = frameos.canvas('trail', Math.max(1, Math.round(width * scale)), Math.max(1, Math.round(height * scale)), '#ffffff')
  const pieces: any[] = []
  if (canvas) {
    const look = `${s.presses}|${ink}|${pale}`
    if (canvas.fresh || look !== drawnLook || drawn > points) {
      if (drawn > 0 || !canvas.fresh) frameos.clear(canvas, '#ffffff')
      drawn = 0
      drawnLook = look
    }
    // From the last point it holds, so the line joins it.
    for (let start = Math.max(0, drawn - 1); drawn < points; start += PIECE) {
      const end = Math.min(points, start + PIECE + 1)
      frameos.draw(canvas, <g>{strokes(start, end, 1)}</g>)
      drawn = end
    }
    pieces.push(<image href={canvas} x="0" y="0" width={width} height={height} preserveAspectRatio="none" />)
  } else {
    for (let start = 0; start < points; start += PIECE) {
      // A piece's line runs on to the next piece's first point, so they join.
      pieces.push(strokes(start, Math.min(points, start + PIECE + 1), scale))
    }
  }

  // Hairlines around the dot, long enough to show past a finger on it. Not
  // across the whole picture: a line that long moves with every move, and a
  // move would repaint all of it.
  const near = radius + at(4)
  const far = radius * 4
  const hair = 1 / scale
  const shown = s.count > 0 // nothing to point at before the first touch
  // What changes at every move (where, how many moves) is on short lines of
  // its own, apart: a move repaints those two and not the whole block.
  const lines = [s.last, `x ${s.x}, y ${s.y}`, `${s.count} events`]
  if (s.moves) lines.push(`${s.moves} moves`)
  return (
    <svg viewBox={`0 0 ${width} ${height}`} width={width} height={height}>
      {canvas ? [] : <rect x="0" y="0" width={width} height={height} fill="#ffffff" />}
      {shown ? [
        <line x1={x} y1={y - far} x2={x} y2={y - near} stroke={hairColor} strokeWidth={hair} />,
        <line x1={x} y1={y + near} x2={x} y2={y + far} stroke={hairColor} strokeWidth={hair} />,
        <line x1={x - far} y1={y} x2={x - near} y2={y} stroke={hairColor} strokeWidth={hair} />,
        <line x1={x + near} y1={y} x2={x + far} y2={y} stroke={hairColor} strokeWidth={hair} />,
      ] : []}
      {pieces}
      {points > 0 ? <circle cx={at(t[0])} cy={at(t[1])} r={radius + at(5)} fill="none" stroke={ink} strokeWidth={r} /> : []}
      {shown ? (mono && !s.down
        ? <circle cx={x} cy={y} r={radius - r / 2} fill="#ffffff" stroke={ink} strokeWidth={r} />
        : <circle cx={x} cy={y} r={radius} fill={ink} />) : []}
      {context.round === true ? lines.map((text, i) => {
        // A round panel: the lines centred in the circle's upper half, where
        // its chord is wide enough for them.
        const rr = Math.min(width, height) / 2
        return (
          <text x={width / 2} y={height / 2 - rr * 0.5 + i * rr * 0.11} fontSize={Math.round(rr * 0.09)} fill="#000000" textAnchor="middle">{text}</text>
        )
      }) : lines.map((text, i) => (
        <text x={at(12)} y={at(38 + i * 32)} fontSize={at(28)} fill="#000000">{text}</text>
      ))}
    </svg>
  )
}
